import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { noop } from 'lodash';
import { useIntl } from 'react-intl';

import type { IDebugRenderTrackerProps } from '@onekeyhq/components';
import {
  ScrollView,
  SizableText,
  Tooltip,
  XStack,
  YStack,
} from '@onekeyhq/components';
import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import { usePromiseResult } from '@onekeyhq/kit/src/hooks/usePromiseResult';
import { useHyperliquidActions } from '@onekeyhq/kit/src/states/jotai/contexts/hyperliquid';
import {
  usePerpsActivePositionAtom,
  usePositionFilterByCurrentTokenAtom,
} from '@onekeyhq/kit/src/states/jotai/contexts/hyperliquid/atoms';
import {
  usePerpsActiveAccountAtom,
  usePerpsActiveAssetAtom,
} from '@onekeyhq/kit-bg/src/states/jotai/atoms';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import platformEnv from '@onekeyhq/shared/src/platformEnv';

import { usePerpUserFundingHistory } from '../../../hooks/usePerpOrderInfoPanel';
import { usePerpsAccountScopedCacheAddress } from '../../../hooks/usePerpsAccountScopedCacheAddress';
import {
  getPerpsAccountScopedListData,
  isPerpsAccountAddressMatched,
  isPerpsAccountScopedDataReady,
} from '../../../utils/accountScopedData';
import {
  type IPerpsMobileLayoutTraceRect,
  getPerpsMobileLayoutTraceRect,
  isPerpsMobileLayoutTraceRectChanged,
  tracePerpsMobileLayout,
} from '../../../utils/mobileLayoutTrace';
import { showCloseAllPositionsDialog } from '../CloseAllPositionsModal';
import { MobilePositionsListHeader } from '../Components/MobilePositionsListHeader';
import { PerpPositionsEmptyState } from '../Components/PerpPositionsEmptyState';
import { type IPositionRowItem, PositionRow } from '../Components/PositionsRow';
import { calcCellAlign, getColumnStyle } from '../utils';
import { PERP_DESKTOP_EMPTY_STATE_TOP_INSET } from '../utils/tableLayout';

import { CommonTableListView, type IColumnConfig } from './CommonTableListView';

import type { LayoutChangeEvent } from 'react-native';

interface IPerpPositionsListProps {
  handleViewTpslOrders: () => void;
  isMobile?: boolean;
  useTabsList?: boolean;
  disableListScroll?: boolean;
}

type IPositionSymbolMetaMap = Awaited<
  ReturnType<typeof backgroundApiProxy.serviceHyperliquid.getSymbolsMetaMap>
>;

function PerpPositionsList({
  handleViewTpslOrders,
  isMobile,
  useTabsList,
  disableListScroll,
}: IPerpPositionsListProps) {
  const intl = useIntl();
  const [actionMeasurement, setActionMeasurement] = useState({
    locale: '',
    width: 160,
  });
  const actionColumnWidth =
    actionMeasurement.locale === intl.locale ? actionMeasurement.width : 160;
  const actionLabels = [
    ETranslations.add_position__action,
    ETranslations.perp_position_market,
    ETranslations.perp_position_limit,
  ].map((id) => intl.formatMessage({ id }));
  const layoutRectsRef = useRef<
    Record<string, IPerpsMobileLayoutTraceRect | undefined>
  >({});
  const [currentUser] = usePerpsActiveAccountAtom();
  const accountScopedAddress = usePerpsAccountScopedCacheAddress();
  const [filterByCurrentToken] = usePositionFilterByCurrentTokenAtom();
  const [activeAsset] = usePerpsActiveAssetAtom();
  const [positions] = usePerpsActivePositionAtom();
  const {
    records: fundingHistory,
    isError: isFundingHistoryError,
    isLoading: isFundingHistoryLoading,
  } = usePerpUserFundingHistory({ isActive: !isMobile });
  const [currentListPage, setCurrentListPage] = useState(1);
  const canMutateScopedPositions = isPerpsAccountAddressMatched({
    activeAccountAddress: currentUser?.accountAddress,
    dataAccountAddress: accountScopedAddress,
  });
  const scopedActivePositions = useMemo(
    () =>
      getPerpsAccountScopedListData({
        activeAccountAddress: accountScopedAddress,
        dataAccountAddress: positions.accountAddress,
        data: positions.activePositions,
      }),
    [accountScopedAddress, positions.accountAddress, positions.activePositions],
  );
  const positionsReady = isPerpsAccountScopedDataReady({
    activeAccountAddress: accountScopedAddress,
    dataAccountAddress: positions.accountAddress,
  });
  const positionsLength = scopedActivePositions.length;
  const positionCoinsKey = useMemo(
    () =>
      [...new Set(scopedActivePositions.map((item) => item.position.coin))]
        .toSorted()
        .join('\u0000'),
    [scopedActivePositions],
  );
  const { result: positionSymbolMetaMap } =
    usePromiseResult<IPositionSymbolMetaMap>(
      async () => {
        const coins = positionCoinsKey ? positionCoinsKey.split('\u0000') : [];
        if (coins.length === 0) {
          return {};
        }
        return backgroundApiProxy.serviceHyperliquid.getSymbolsMetaMap({
          coins,
        });
      },
      [positionCoinsKey],
      {
        initResult: {},
        undefinedResultIfError: true,
      },
    );
  useEffect(() => {
    noop(currentUser?.accountAddress);
    setCurrentListPage(1);
  }, [currentUser?.accountAddress]);

  const columnsConfig: IColumnConfig[] = useMemo(() => {
    return [
      {
        key: 'asset',
        title: intl.formatMessage({
          id: ETranslations.perp_token_selector_asset,
        }),
        width: 110,
        align: 'left',
      },
      {
        key: 'size',
        title: intl.formatMessage({
          id: ETranslations.perp_position_position_size,
        }),
        minWidth: 120,
        align: 'left',
        flex: 1,
      },
      {
        key: 'entryPrice',
        title: intl.formatMessage({
          id: ETranslations.perp_position_entry_price,
        }),
        minWidth: 100,
        align: 'left',
        flex: 1,
      },
      {
        key: 'markPrice',
        title: intl.formatMessage({
          id: ETranslations.perp_position_mark_price,
        }),
        minWidth: 100,
        align: 'left',
        flex: 1,
      },
      {
        key: 'liqPrice',
        title: intl.formatMessage({
          id: ETranslations.perp_position_liq_price,
        }),
        minWidth: 100,
        align: 'left',
        flex: 1,
      },
      {
        key: 'pnl',
        title: intl.formatMessage({
          id: ETranslations.perp_position_pnl,
        }),
        minWidth: 180,
        align: 'left',
        flex: 1,
      },
      {
        key: 'margin',
        title: intl.formatMessage({
          id: ETranslations.perp_position_margin,
        }),
        minWidth: 100,
        align: 'left',
        flex: 1,
        tooltip: intl.formatMessage({
          id: ETranslations.perp_position_margin_tooltip,
        }),
      },
      {
        key: 'funding',
        title: intl.formatMessage({
          id: ETranslations.perp_position_funding_2,
        }),
        minWidth: 100,
        align: 'left',
        flex: 1,
        tooltip: intl.formatMessage({
          id: ETranslations.perp_position_margin_tooltip_funding,
        }),
      },
      {
        key: 'TPSL',
        title: intl.formatMessage({
          id: ETranslations.perp_position_tp_sl,
        }),
        minWidth: 140,
        align: 'left',
        flex: 1,
      },
      {
        key: 'closeAll',
        title: intl.formatMessage({
          id: ETranslations.perp_position_close,
        }),
        width: actionColumnWidth,
        align: 'right',
        flex: 1,
        fixed: positionsLength > 0,
        ...(positionsLength > 0 &&
          canMutateScopedPositions && {
            onPress: () =>
              showCloseAllPositionsDialog(undefined, accountScopedAddress),
          }),
      },
    ];
  }, [
    accountScopedAddress,
    canMutateScopedPositions,
    intl,
    positionsLength,
    actionColumnWidth,
  ]);
  const totalMinWidth = useMemo(
    () =>
      columnsConfig.reduce(
        (sum, col) => sum + (col.width || col.minWidth || 0),
        0,
      ),
    [columnsConfig],
  );

  // Keep each row on the same positions snapshot that decided list emptiness.
  const mockedPositions = useMemo<IPositionRowItem[]>(() => {
    if (!isMobile || !filterByCurrentToken || !activeAsset?.coin) {
      return scopedActivePositions.map((activePosition, index) => ({
        index,
        activePosition,
        assetId: positionSymbolMetaMap?.[activePosition.position.coin]?.assetId,
      }));
    }
    return scopedActivePositions
      .map((activePosition, originalIndex) => ({
        index: originalIndex,
        activePosition,
        assetId: positionSymbolMetaMap?.[activePosition.position.coin]?.assetId,
      }))
      .filter((item) => item.activePosition.position.coin === activeAsset.coin);
  }, [
    scopedActivePositions,
    isMobile,
    filterByCurrentToken,
    activeAsset?.coin,
    positionSymbolMetaMap,
  ]);

  const handleTraceLayout = useCallback(
    (name: string, event: LayoutChangeEvent) => {
      if (!isMobile) {
        return;
      }
      const rect = getPerpsMobileLayoutTraceRect(event);
      if (
        isPerpsMobileLayoutTraceRectChanged(layoutRectsRef.current[name], rect)
      ) {
        tracePerpsMobileLayout(`positionsList.${name}.layout`, {
          rect,
          mockedPositionsLength: mockedPositions.length,
          activePositionsLength: scopedActivePositions.length,
          filterByCurrentToken,
          activeCoin: activeAsset?.coin,
          hasAccountAddress: Boolean(accountScopedAddress),
          useTabsList,
          disableListScroll,
          positionsReady,
        });
        layoutRectsRef.current[name] = rect;
      }
    },
    [
      activeAsset?.coin,
      accountScopedAddress,
      disableListScroll,
      filterByCurrentToken,
      isMobile,
      mockedPositions.length,
      positionsReady,
      scopedActivePositions.length,
      useTabsList,
    ],
  );

  useEffect(() => {
    if (!isMobile) {
      return;
    }
    tracePerpsMobileLayout('positionsList.state', {
      positionsLength,
      mockedPositionsLength: mockedPositions.length,
      activePositionsLength: scopedActivePositions.length,
      filterByCurrentToken,
      activeCoin: activeAsset?.coin,
      hasAccountAddress: Boolean(accountScopedAddress),
      useTabsList,
      disableListScroll,
      positionsReady,
    });
  }, [
    activeAsset?.coin,
    accountScopedAddress,
    disableListScroll,
    filterByCurrentToken,
    isMobile,
    mockedPositions.length,
    positionsReady,
    positionsLength,
    scopedActivePositions.length,
    useTabsList,
  ]);

  const renderPositionRow = (
    item: IPositionRowItem,
    _index: number,
    renderMode?: 'full' | 'left' | 'right',
    isHovered?: boolean,
    onHoverChange?: (index: number | null) => void,
  ) => (
    <PositionRow
      mockedPosition={item}
      isMobile={isMobile}
      cellMinWidth={totalMinWidth}
      columnConfigs={columnsConfig}
      handleViewTpslOrders={handleViewTpslOrders}
      renderMode={renderMode}
      isHovered={isHovered}
      onHoverChange={onHoverChange}
      fundingHistory={fundingHistory}
      isFundingHistoryLoading={isFundingHistoryLoading}
      isFundingHistoryError={isFundingHistoryError}
    />
  );
  const keyExtractor = useCallback((item: IPositionRowItem) => {
    return item.activePosition.position.coin;
  }, []);
  const actions = useHyperliquidActions();
  const listViewDebugRenderTrackerProps = useMemo(
    (): IDebugRenderTrackerProps => ({
      name: 'PerpPositionsList',
      position: 'top-left',
    }),
    [],
  );

  const renderDesktopHeaderCell = (column: IColumnConfig, index: number) => (
    <XStack
      key={`${column.key}-${index}`}
      {...getColumnStyle(column)}
      justifyContent={calcCellAlign(column.align) as any}
      cursor="default"
    >
      {column.tooltip ? (
        <Tooltip
          placement="top"
          renderTrigger={
            <SizableText
              size="$bodySmMedium"
              borderBottomWidth="$px"
              borderTopWidth={0}
              borderLeftWidth={0}
              borderRightWidth={0}
              borderBottomColor="$border"
              borderStyle="dashed"
              cursor="help"
              color="$textSubdued"
              textAlign={column.align || 'left'}
            >
              {column.title}
            </SizableText>
          }
          renderContent={column.tooltip}
        />
      ) : (
        <SizableText
          size="$bodySmMedium"
          borderBottomWidth="$px"
          borderBottomColor="transparent"
          color="$textSubdued"
          textAlign={column.align || 'left'}
        >
          {column.title}
        </SizableText>
      )}
    </XStack>
  );

  if (!isMobile && positionsReady && mockedPositions.length === 0) {
    return (
      <YStack flex={1} width="100%">
        {/* Row wrapper keeps the ScrollView's flexGrow horizontal; in a column
            parent it would split the pane height with the empty state. */}
        <XStack
          width="100%"
          borderBottomWidth="$px"
          borderBottomColor="$borderSubdued"
          bg="$bgApp"
        >
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            nestedScrollEnabled
            style={{ flex: 1 }}
            contentContainerStyle={{
              minWidth: totalMinWidth,
              flexGrow: 1,
            }}
          >
            <XStack
              flex={1}
              py="$2"
              pl="$5"
              pr="$3"
              display="flex"
              minWidth={totalMinWidth}
              width="100%"
            >
              {columnsConfig.map(renderDesktopHeaderCell)}
            </XStack>
          </ScrollView>
        </XStack>
        <YStack
          flex={1}
          width="100%"
          minHeight={0}
          pt={PERP_DESKTOP_EMPTY_STATE_TOP_INSET}
        >
          <PerpPositionsEmptyState />
        </YStack>
      </YStack>
    );
  }

  return (
    <YStack flex={1} onLayout={(event) => handleTraceLayout('root', event)}>
      {!isMobile && platformEnv.isRuntimeBrowser ? (
        <YStack
          key={intl.locale}
          position="absolute"
          opacity={0}
          pointerEvents="none"
          aria-hidden
          alignItems="flex-start"
          $platform-web={{ width: 'max-content' }}
          onLayout={(event) => {
            const width = Math.ceil(event.nativeEvent.layout.width);
            if (width > 0) {
              setActionMeasurement((previous) =>
                previous.locale === intl.locale && previous.width === width
                  ? previous
                  : { locale: intl.locale, width },
              );
            }
          }}
        >
          {/* Measure the widest hover weight so actions never outgrow the fixed column. */}
          <XStack gap="$2">
            {actionLabels.map((label, index) => (
              <SizableText
                key={index}
                size="$bodySmMedium"
                fontWeight={600}
                flexShrink={0}
              >
                {label}
              </SizableText>
            ))}
          </XStack>
          <SizableText size="$bodySmMedium" fontWeight={600}>
            {intl.formatMessage({ id: ETranslations.perp_position_close })}
          </SizableText>
        </YStack>
      ) : null}
      <CommonTableListView
        onPullToRefresh={async () => {
          await actions.current.refreshAllPerpsData();
        }}
        listViewDebugRenderTrackerProps={listViewDebugRenderTrackerProps}
        useTabsList={useTabsList}
        disableListScroll={disableListScroll}
        currentListPage={currentListPage}
        setCurrentListPage={setCurrentListPage}
        enablePagination={!isMobile}
        columns={columnsConfig}
        minTableWidth={totalMinWidth}
        data={mockedPositions}
        isMobile={isMobile}
        renderRow={renderPositionRow}
        keyExtractor={keyExtractor}
        listLoading={!positionsReady}
        ListEmptyComponent={<PerpPositionsEmptyState isMobile={isMobile} />}
        emptyMessage={intl.formatMessage({
          id: ETranslations.perp_position_empty,
        })}
        emptySubMessage={intl.formatMessage({
          id: ETranslations.perp_position_empty_desc,
        })}
        ListHeaderComponent={
          isMobile ? (
            <MobilePositionsListHeader
              totalPositionCount={scopedActivePositions.length}
              canCloseAll={canMutateScopedPositions}
              scopedAccountAddress={accountScopedAddress}
            />
          ) : null
        }
      />
    </YStack>
  );
}

export { PerpPositionsList };
