import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { BigNumber } from 'bignumber.js';
import { isNil } from 'lodash';
import { type IntlShape, useIntl } from 'react-intl';

import {
  Button,
  Dialog,
  Divider,
  Icon,
  SizableText,
  Toast,
  XStack,
  YStack,
} from '@onekeyhq/components';
import type { IDialogInstance } from '@onekeyhq/components';
import backgroundApiProxy from '@onekeyhq/kit/src/background/instance/backgroundApiProxy';
import { usePromiseResult } from '@onekeyhq/kit/src/hooks/usePromiseResult';
import {
  useHyperliquidActions,
  usePerpsAllMidsAtom,
} from '@onekeyhq/kit/src/states/jotai/contexts/hyperliquid';
import { ETranslations } from '@onekeyhq/shared/src/locale';
import platformEnv from '@onekeyhq/shared/src/platformEnv';
import {
  calculateProfitLoss,
  formatHlSize,
  formatPriceToSignificantDigits,
  getValidPerpsPrice,
  parseDexCoin,
  validateSizeInput,
} from '@onekeyhq/shared/src/utils/perpsUtils';
import type { IWsWebData2 } from '@onekeyhq/shared/types/hyperliquid/sdk';

import { useCoinOrderBookTop } from '../../hooks/useCoinOrderBookTop';
import { PerpsProviderMirror } from '../../PerpsProviderMirror';
import { getAggressiveLimitPriceWarning } from '../../utils/aggressiveLimitPrice';
import {
  PERP_DIALOG_BUTTON_SIZE,
  PERP_KEYBOARD_AWARE_DIALOG_CONTENT_CONTAINER_PROPS,
} from '../PerpDialogLayout';
import { PerpKeyboardAwareDialogContent } from '../PerpKeyboardAwareDialogContent';
import { PerpsSlider } from '../PerpsSlider';
import { TradingGuardWrapper } from '../TradingGuardWrapper';
import { PriceInput } from '../TradingPanel/inputs/PriceInput';
import { TradingFormInput } from '../TradingPanel/inputs/TradingFormInput';
import { AggressiveLimitPriceWarning } from '../TradingPanel/modals/AggressiveLimitPriceWarning';

type IPosition =
  IWsWebData2['clearinghouseState']['assetPositions'][number]['position'];

type ICloseType = 'market' | 'limit';

interface IClosePositionFormData {
  type: ICloseType;
  amount: string;
  limitPrice: string;
  percentage: number;
}

interface IClosePositionParams {
  position: IPosition;
  type: ICloseType;
}

interface IClosePositionFormProps extends IClosePositionParams {
  onClose: () => void;
}

const ClosePositionForm = memo(
  ({ position, type, onClose }: IClosePositionFormProps) => {
    const intl = useIntl();
    const [allMids] = usePerpsAllMidsAtom();
    const hyperliquidActions = useHyperliquidActions();

    const { result: tokenInfo } = usePromiseResult(async () => {
      return backgroundApiProxy.serviceHyperliquid.getSymbolMeta({
        coin: position.coin,
      });
    }, [position.coin]);
    const szDecimals = tokenInfo?.universe?.szDecimals ?? 2;
    const assetId = tokenInfo?.assetId;

    const atomMidPrice = useMemo(() => {
      return getValidPerpsPrice(allMids?.mids?.[position.coin]);
    }, [allMids?.mids, position.coin]);

    const tokenDisplayName = useMemo(() => {
      return parseDexCoin(position.coin).displayName;
    }, [position.coin]);

    const positionSize = useMemo(() => {
      const size = new BigNumber(position.szi || '0').abs();
      return size;
    }, [position.szi]);

    const isLongPosition = useMemo(
      () => new BigNumber(position.szi || '0').gte(0),
      [position.szi],
    );

    const [formData, setFormData] = useState<IClosePositionFormData>({
      type,
      amount: positionSize.toFixed(),
      limitPrice: '',
      percentage: 100,
    });

    const [sliderPercentage, setSliderPercentage] = useState(
      formData.percentage,
    );

    const [userSetPrice, setUserSetPrice] = useState(false);
    const initPriceRef = useRef(false);
    const isMountedRef = useRef(true);

    const [referencePriceResolved, setReferencePriceResolved] = useState(false);
    // The main runtime only sees mids the WebSocket has already forwarded,
    // which lags by seconds on cold start, so the gate polls the same
    // background price source the submit uses instead of waiting on the atom.
    const { result: referencePrice } = usePromiseResult(
      async () => {
        if (atomMidPrice) {
          return atomMidPrice;
        }
        const price =
          await backgroundApiProxy.serviceHyperliquid.getMarketOrderReferencePrice(
            position.coin,
          );
        if (isMountedRef.current) {
          setReferencePriceResolved(true);
        }
        return price;
      },
      [atomMidPrice, position.coin],
      { pollingInterval: 2000, checkIsFocused: false },
    );
    const midPrice = atomMidPrice ?? getValidPerpsPrice(referencePrice);
    const isMarketPriceUnavailable = !midPrice && referencePriceResolved;
    const priceUnavailableToastShownRef = useRef(false);

    useEffect(() => {
      setSliderPercentage(formData.percentage);
    }, [formData.percentage, setSliderPercentage]);

    useEffect(() => {
      if (
        formData.type === 'market' &&
        isMarketPriceUnavailable &&
        !priceUnavailableToastShownRef.current
      ) {
        priceUnavailableToastShownRef.current = true;
        // TODO(i18n): pre-existing English literal shared with the submit
        // path below and closeAllPositions; needs a Lokalise key.
        Toast.error({
          title: 'Unable to get current market price',
        });
      }
    }, [formData.type, isMarketPriceUnavailable]);

    useEffect(() => {
      if (!midPrice) return;

      if (!initPriceRef.current && !userSetPrice && isMountedRef.current) {
        setFormData((prev) => ({
          ...prev,
          limitPrice: formatPriceToSignificantDigits(midPrice),
        }));
        initPriceRef.current = true;
      }
    }, [midPrice, userSetPrice]);

    useEffect(() => {
      return () => {
        isMountedRef.current = false;
      };
    }, []);

    const [isSubmitting, setIsSubmitting] = useState(false);
    const submittingRef = useRef(false);
    const orderBookTop = useCoinOrderBookTop(position.coin);

    const aggressiveLimitPriceWarning = useMemo(
      () =>
        formData.type === 'limit'
          ? getAggressiveLimitPriceWarning({
              side: isLongPosition ? 'short' : 'long',
              limitPrice: formData.limitPrice,
              bestBid: orderBookTop.bestBid,
              bestAsk: orderBookTop.bestAsk,
            })
          : undefined,
      [
        formData.limitPrice,
        formData.type,
        isLongPosition,
        orderBookTop.bestAsk,
        orderBookTop.bestBid,
      ],
    );

    const calculatedAmount = useMemo(() => {
      const percentage = Number.isNaN(formData.percentage)
        ? 0
        : formData.percentage;
      const amount = positionSize.multipliedBy(percentage).dividedBy(100);
      // Floor-truncate to szDecimals to match HL lot-size rule (no over-rounding).
      return formatHlSize(amount, szDecimals) || '0';
    }, [positionSize, formData.percentage, szDecimals]);

    const handlePercentageChange = useCallback(
      (percentage: number) => {
        // Compute size at full precision then floor-truncate via formatHlSize
        // (avoid HALF_UP toFixed which can produce a size larger than the
        // requested percentage of the position).
        const amount = positionSize.multipliedBy(percentage).dividedBy(100);
        setFormData((prev) => ({
          ...prev,
          percentage,
          amount: formatHlSize(amount, szDecimals) || '0',
        }));
      },
      [positionSize, szDecimals],
    );

    const handleAmountChange = useCallback(
      (value: string) => {
        const processedValue = value.replace(/。/g, '.');

        if (processedValue === '' || processedValue === '.') {
          setFormData((prev) => ({
            ...prev,
            amount: processedValue,
            percentage: processedValue === '' ? 0 : prev.percentage,
          }));
          return;
        }

        const numericValue = new BigNumber(processedValue);
        if (numericValue.isNaN()) {
          return;
        }

        if (numericValue.gt(positionSize)) {
          setFormData((prev) => ({
            ...prev,
            amount: formatHlSize(positionSize, szDecimals) || '0',
            percentage: 100,
          }));
          return;
        }

        const percentage = positionSize.gt(0)
          ? numericValue.dividedBy(positionSize).multipliedBy(100).toNumber()
          : 0;

        setFormData((prev) => ({
          ...prev,
          amount: processedValue,
          percentage: Math.min(100, Math.max(0, percentage)),
        }));
      },
      [positionSize, szDecimals],
    );

    const handleLimitPriceChange = useCallback(
      (value: string) => {
        const processedValue = value.replace(/。/g, '.');
        setFormData((prev) => ({
          ...prev,
          limitPrice: processedValue,
        }));

        if (!userSetPrice) {
          setUserSetPrice(true);
        }
      },
      [userSetPrice],
    );

    const handleUseMid = useCallback(() => {
      const latestMidPrice = midPrice;
      if (latestMidPrice) {
        setFormData((prev) => ({
          ...prev,
          limitPrice: formatPriceToSignificantDigits(latestMidPrice),
        }));
        setUserSetPrice(false);
        initPriceRef.current = true;
      }
    }, [midPrice]);

    const handleTypeChange = useCallback((value: string) => {
      setFormData((prev) => ({
        ...prev,
        type: value as ICloseType,
      }));
    }, []);

    const handleSubmit = useCallback(async () => {
      // The disabled state lands one render late, so same-frame double taps
      // would otherwise send a second reduce-only order for the full size.
      if (submittingRef.current) {
        return;
      }
      submittingRef.current = true;
      let submitted = false;
      try {
        if (isNil(assetId) || Number.isNaN(assetId)) {
          return;
        }
        if (isMountedRef.current) {
          setIsSubmitting(true);
        }

        const closeAmount = formData.amount || calculatedAmount;
        const closeAmountBN = new BigNumber(closeAmount);

        if (!closeAmount || closeAmountBN.lte(0)) {
          Toast.error({
            title: 'Please enter a valid amount',
          });
          return;
        }

        if (formData.type === 'market') {
          const latestMidPrice =
            await backgroundApiProxy.serviceHyperliquid.getMarketOrderReferencePrice(
              position.coin,
            );
          if (!latestMidPrice) {
            Toast.error({
              title: 'Unable to get current market price',
            });
            return;
          }

          await hyperliquidActions.current.ordersClose([
            {
              assetId,
              isBuy: isLongPosition,
              size: closeAmount,
              midPx: latestMidPrice,
            },
          ]);
        } else {
          const limitPriceBN = new BigNumber(formData.limitPrice || '0');
          if (!formData.limitPrice || limitPriceBN.lte(0)) {
            Toast.error({
              title: 'Please enter a valid limit price',
            });
            return;
          }

          await hyperliquidActions.current.ordersClose([
            {
              assetId,
              isBuy: isLongPosition,
              size: closeAmount,
              limitPx: formData.limitPrice,
            },
          ]);
        }

        hyperliquidActions.current.resetTradingForm();
        // The dialog stays mounted through its exit animation, so the guard
        // must stay armed after success or a tap there places a second order.
        submitted = true;
        if (isMountedRef.current) {
          onClose();
        }
      } finally {
        if (!submitted) {
          submittingRef.current = false;
          if (isMountedRef.current) {
            setIsSubmitting(false);
          }
        }
      }
    }, [
      formData.amount,
      formData.type,
      formData.limitPrice,
      calculatedAmount,
      assetId,
      position.coin,
      isLongPosition,
      hyperliquidActions,
      onClose,
    ]);
    const entryPrice = useMemo(() => {
      return position?.entryPx || '0';
    }, [position]);

    const estimatedProfit = useMemo(() => {
      const exitPrice =
        formData.type === 'market' ? midPrice : formData.limitPrice;
      if (!exitPrice || !position.entryPx) return '$0.00';

      const amount = formData.amount || positionSize.toFixed(szDecimals);
      if (!amount) return '$0.00';

      return calculateProfitLoss({
        entryPrice: position.entryPx,
        exitPrice,
        amount,
        side: isLongPosition ? 'long' : 'short',
        formatOptions: {
          currency: '$',
          decimals: 2,
          showSign: false,
        },
      });
    }, [
      formData.type,
      midPrice,
      formData.amount,
      formData.limitPrice,
      position.entryPx,
      positionSize,
      isLongPosition,
      szDecimals,
    ]);

    const isAmountValid = useMemo(() => {
      const amount = formData.amount || calculatedAmount;
      if (!amount) return false;

      const amountBN = new BigNumber(amount);
      if (!amountBN.isFinite()) return false;

      return amountBN.gt(0) && amountBN.lte(positionSize);
    }, [formData.amount, calculatedAmount, positionSize]);

    const isPriceValid = useMemo(() => {
      if (formData.type === 'market') {
        return Boolean(midPrice);
      }

      const limitPrice = new BigNumber(formData.limitPrice || '0');
      if (!limitPrice.isFinite() || limitPrice.isZero()) return false;

      const liquidationPrice = position.liquidationPx;
      if (liquidationPrice) {
        if (
          (!isLongPosition && limitPrice.gt(liquidationPrice)) ||
          (isLongPosition && limitPrice.lt(liquidationPrice))
        ) {
          return false;
        }
      }

      return limitPrice.gt(0);
    }, [
      formData.type,
      formData.limitPrice,
      midPrice,
      isLongPosition,
      position.liquidationPx,
    ]);

    const isFormValid = useMemo(() => {
      return isAmountValid && isPriceValid;
    }, [isAmountValid, isPriceValid]);

    return (
      <YStack gap="$4">
        {aggressiveLimitPriceWarning ? (
          <AggressiveLimitPriceWarning warning={aggressiveLimitPriceWarning} />
        ) : null}

        <YStack gap="$3">
          <XStack justifyContent="space-between" alignItems="center">
            <SizableText size="$bodyMd" color="$textSubdued">
              {intl.formatMessage({
                id: ETranslations.perp_token_selector_asset,
              })}
            </SizableText>
            <SizableText size="$bodyMdMedium">{tokenDisplayName}</SizableText>
          </XStack>

          <XStack justifyContent="space-between" alignItems="center">
            <SizableText size="$bodyMd" color="$textSubdued">
              {intl.formatMessage({
                id: ETranslations.perp_position_position_size,
              })}
            </SizableText>
            <SizableText size="$bodyMdMedium">
              {positionSize.toNumber()} {tokenDisplayName}
            </SizableText>
          </XStack>
          <XStack justifyContent="space-between" alignItems="center">
            <SizableText size="$bodyMd" color="$textSubdued">
              {intl.formatMessage({
                id: ETranslations.perp_position_entry_price,
              })}
            </SizableText>
            <SizableText size="$bodyMdMedium">{entryPrice}</SizableText>
          </XStack>

          {/* <XStack justifyContent="space-between" alignItems="center">
            <SizableText size="$bodyMd" color="$textSubdued">
              {intl.formatMessage({
                id: ETranslations.perp_position_mark_price,
              })}
            </SizableText>
            <MarkPrice coin={position.coin} />
          </XStack> */}

          <XStack justifyContent="space-between" alignItems="center">
            <SizableText size="$bodyMd" color="$textSubdued">
              {intl.formatMessage({
                id: ETranslations.perp_trade_order_type,
              })}
            </SizableText>
            <XStack
              alignItems="center"
              onPress={() =>
                handleTypeChange(formData.type === 'limit' ? 'market' : 'limit')
              }
              gap="$1"
              cursor="default"
            >
              <SizableText size="$bodyMdMedium">
                {formData.type === 'limit'
                  ? intl.formatMessage({
                      id: ETranslations.perp_trade_limit,
                    })
                  : intl.formatMessage({
                      id: ETranslations.perp_trade_market,
                    })}
              </SizableText>
              <Icon
                name="RepeatOutline"
                size="$3.5"
                color="$text"
                fontWeight="600"
              />
            </XStack>
          </XStack>
        </YStack>
        <Divider />
        {formData.type === 'limit' ? (
          <PriceInput
            label={intl.formatMessage({
              id: ETranslations.perp_trade_limit_pirce,
            })}
            value={formData.limitPrice}
            onChange={handleLimitPriceChange}
            onUseMidPrice={handleUseMid}
            midPriceDisabled={!midPrice}
            szDecimals={szDecimals}
            ifOnDialog
          />
        ) : null}

        <TradingFormInput
          label={intl.formatMessage({
            id: ETranslations.dexmarket_details_history_amount,
          })}
          value={
            formData.amount || (formData.percentage > 0 ? calculatedAmount : '')
          }
          onChange={handleAmountChange}
          suffix={tokenDisplayName}
          validator={(value: string) => {
            const processedValue = value.replace(/。/g, '.');
            return validateSizeInput(processedValue, szDecimals);
          }}
          ifOnDialog
        />

        <PerpsSlider
          value={sliderPercentage}
          onChange={handlePercentageChange}
          max={100}
          min={0}
          segments={4}
          snapTapToSegment
          sliderHeight={4}
          showBubble
        />

        <XStack justifyContent="space-between" gap="$1">
          <SizableText size="$bodyMd" color="$textSubdued">
            {intl.formatMessage({
              id: ETranslations.perp_tp_sl_profit,
            })}
          </SizableText>
          <SizableText
            size="$bodyMdMedium"
            color={estimatedProfit.startsWith('-') ? '$red11' : '$green11'}
          >
            {estimatedProfit}
          </SizableText>
        </XStack>
        <YStack pt={platformEnv.isNative ? '$4' : 0}>
          <TradingGuardWrapper buttonSize={PERP_DIALOG_BUTTON_SIZE}>
            <Button
              testID="perp-processed-value-btn"
              size={PERP_DIALOG_BUTTON_SIZE}
              variant="primary"
              onPress={handleSubmit}
              disabled={!isFormValid || isSubmitting}
              loading={
                isSubmitting ||
                (formData.type === 'market' &&
                  !isPriceValid &&
                  !isMarketPriceUnavailable)
              }
            >
              {intl.formatMessage({
                id: ETranslations.perp_confirm_order,
              })}
            </Button>{' '}
          </TradingGuardWrapper>
        </YStack>
      </YStack>
    );
  },
);

ClosePositionForm.displayName = 'ClosePositionForm';

// Dialog.show mounts its portal asynchronously, so isExist() reports false
// during the first frames; the grace window covers same-frame double taps.
const CLOSE_DIALOG_MOUNT_GRACE_MS = 1000;
let activeCloseDialog: IDialogInstance | undefined;
let activeCloseDialogShownAt = 0;

export function showClosePositionDialog({
  position,
  type,
  intl,
}: IClosePositionParams & { intl: IntlShape }) {
  // Rapid taps would stack dialogs, each holding its own position snapshot,
  // so only one close dialog is kept alive at a time.
  if (
    activeCloseDialog &&
    (activeCloseDialog.isExist() ||
      Date.now() - activeCloseDialogShownAt < CLOSE_DIALOG_MOUNT_GRACE_MS)
  ) {
    return activeCloseDialog;
  }
  const dialogInstance = Dialog.show({
    title: intl.formatMessage({
      id: ETranslations.perp_close_position_title,
    }),
    disableDrag: true,
    onClose: () => {
      if (activeCloseDialog === dialogInstance) {
        activeCloseDialog = undefined;
      }
    },
    renderContent: (
      <PerpsProviderMirror>
        <PerpKeyboardAwareDialogContent>
          <ClosePositionForm
            position={position}
            type={type}
            onClose={() => dialogInstance.close()}
          />
        </PerpKeyboardAwareDialogContent>
      </PerpsProviderMirror>
    ),
    contentContainerProps: PERP_KEYBOARD_AWARE_DIALOG_CONTENT_CONTAINER_PROPS,
    showFooter: false,
  });
  activeCloseDialog = dialogInstance;
  activeCloseDialogShownAt = Date.now();

  return dialogInstance;
}
